CREATE TABLE roles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(80) NOT NULL);
CREATE TABLE usuarios(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(120) NOT NULL,activo BOOLEAN NOT NULL DEFAULT TRUE,rol_id BIGINT NOT NULL REFERENCES roles(id),fecha_creacion TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO roles(codigo,nombre) VALUES('ADMINISTRADOR','Administrador'),('TESORERIA','Tesorería'),('OPERADOR','Operador de riego');
CREATE TABLE agricultores(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,dni VARCHAR(8) NOT NULL UNIQUE,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(120) NOT NULL,telefono VARCHAR(20),sector VARCHAR(30) NOT NULL,estado VARCHAR(20) NOT NULL);
CREATE TABLE parcelas(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(100) NOT NULL,hectareas NUMERIC(10,2) NOT NULL,cultivo VARCHAR(100),agricultor_id BIGINT NOT NULL REFERENCES agricultores(id));
CREATE TABLE turnos_riego(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,fecha DATE NOT NULL,hora_inicio TIME NOT NULL,hora_fin TIME NOT NULL,estado VARCHAR(20) NOT NULL,observaciones VARCHAR(255),parcela_id BIGINT NOT NULL REFERENCES parcelas(id));
CREATE TABLE pagos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,monto NUMERIC(12,2) NOT NULL,fecha DATE NOT NULL,concepto VARCHAR(150) NOT NULL,comprobante VARCHAR(50) NOT NULL UNIQUE,metodo VARCHAR(30) NOT NULL,agricultor_id BIGINT NOT NULL REFERENCES agricultores(id));
